sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	// Automatic update of the User Type on the corresponding applicative access - START
	gs.addInfoMessage('BR PEAR - AIU-BPa triggered by the update of Bpa ' + current.display_name);
	var aa_user_type = [];
	var bpa_user_type;
	var bpa_aa = [];
	var bpa;
	var aa = new GlideRecord('x_587457_pear_applicative_access');
	aa.addEncodedQuery(new x_587457_pear.PEAR_Utils3().getConcernedApplicativeAccessOfBusinessPart(current.sys_id));
	aa.query();
	while(aa.next())
	{
		bpa = new GlideRecord('x_587457_pear_business_part_of_app_access');
		bpa.addEncodedQuery(new x_587457_pear.PEAR_Utils3().getConcernedfBusinessPartsOfApplicativeAccess(aa.sys_id));
		bpa.query();
		while(bpa.next())
		{
			if(!bpa_aa.toString().contains(bpa.sys_id.toString()))
				bpa_aa.push(bpa.sys_id.toString());
			// gs.addInfoMessage("aa " + aa.label + ' bpa ' + bpa.label + ' bpa user types ' + bpa.user_type_list);
			bpa_user_type = bpa.user_type_list.toString().split(',')
			for(i=0;i<bpa_user_type.length;i++)
				if(!aa_user_type.toString().contains(bpa_user_type[i].toString()))
					aa_user_type.push(bpa_user_type[i].toString())


		}
		// gs.addInfoMessage("aa " + aa.label + ' aa_user_type ' + aa_user_type.toString());
		aa.user_type = aa_user_type.toString();
		aa.business_part = bpa_aa.toString();
		aa.update();

	}
	// Automatic update of the User Type on the corresponding applicative access - END

	// Automatic update of the User Type, Application, Access profile and License lists on the corresponding business profiles - START
	var bp_user_type = [];
	var bp = new GlideRecord('x_587457_pear_business_profile');
	bp.get(current.business_profile_id);
	// gs.addInfoMessage('Updating business profile ' + bp.label)
	bpa = new GlideRecord('x_587457_pear_business_part_of_app_access');
	bpa.addQuery('business_profile_id',bp.sys_id);
	bpa.query();
	// gs.addInfoMessage('bpa count ' + bpa.getRowCount())
	while(bpa.next())
	{
		bpa_user_type = bpa.user_type_list.toString().split(',')
		for(i=0;i<bpa_user_type.length;i++)
			if(!bp_user_type.toString().contains(bpa_user_type[i].toString()))
				bp_user_type.push(bpa_user_type[i].toString())

	}
	bp.user_type = bp_user_type.toString();

	var applications = [];
	var app = new GlideRecord('x_587457_pear_application');
	app.addEncodedQuery(new x_587457_pear.PEAR_Utils3().getApplicationsOfBusinessProfile(bp.sys_id));
	app.query();
	while(app.next())
		applications.push(app.sys_id.toString());
	bp.application = applications.toString();

	var access_profiles = [];
	var ap = new GlideRecord('x_587457_pear_access_profile');
	ap.addEncodedQuery(new x_587457_pear.PEAR_Utils3().getAccessProfilesOfBusinessProfile(bp.sys_id));
	ap.orderBy('label');
	ap.query();
	while(ap.next())
		access_profiles.push(ap.sys_id.toString())
	bp.access_profile = access_profiles.toString();

	var licenses = [];
	var l = new GlideRecord('x_587457_pear_license');
	l.addEncodedQuery(new x_587457_pear.PEAR_Utils3().getLicensesOfBusinessProfile(bp.sys_id));
	l.orderBy('label');
	l.query();
	while(l.next())
		licenses.push(l.sys_id.toString());
	bp.license = licenses.toString(); 


	bp.update();
	// Automatic update of the User Type, Application, Access profile and License lists on the corresponding business profiles - END




	// Automatic update of Business Part (concerned applicative access) - START

	var bpa_aa = [];
	var aa = new GlideRecord('x_587457_pear_applicative_access');
	aa.addEncodedQuery(new x_587457_pear.PEAR_Utils3().getConcernedApplicativeAccessOfBusinessPart(current.sys_id));
	aa.query();
	while(aa.next())
		bpa_aa.push(aa.sys_id.toString())

	current.applicative_access = bpa_aa.toString();
	current.update();
	// Automatic update of Business Part (concerned applicative access) - END	


})(current, previous);
